#!/usr/bin/env python3"""Test if bridge can connect to mosquitto inside Docker network"""import paho.mqtt.client as mqttimport jsonimport timeimport logginglogging.basicConfig(level=logging.INFO, format='%(message)s')logger = logging.getLogger()# Try to connect to mosquitto from Docker context (as bridge would)msg_received = []def on_message(c, u, m):    msg_received.append(m.payload.decode())    logger.info(f"Γ£ô Received: {m.payload.decode()[:50]}")def on_connect(c, u, f, rc):    if rc == 0:        logger.info(f"Γ£ô Connected to mosquitto")        c.subscribe("sensors/gas")        logger.info(f"Γ£ô Subscribed to sensors/gas")    else:        logger.error(f"Γ£ù Failed to connect: {rc}")try:    logger.info("Attempting to connect to mosquitto...")    client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION1)    client.on_connect = on_connect    client.on_message = on_message    client.connect("mosquitto", 1883, 60)    client.loop_start()        logger.info("Waiting 3 seconds for messages...")    time.sleep(3)        client.loop_stop()    client.disconnect()        if msg_received:        logger.info(f"Γ£ô SUCCESS: Received {len(msg_received)} message(s)")    else:        logger.warning(f"Γ£ù No messages received (but connection was successful)")        except Exception as e:    logger.error(f"Γ£ù Error: {e}", exc_info=True)